package com.toabea.closet.config;
import com.toabea.closet.common.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration public class BootstrapAdmin { @Bean CommandLineRunner seedAdmin(AdminUserRepository repo,PasswordEncoder encoder,@Value("${app.bootstrap-admin.username:}") String username,@Value("${app.bootstrap-admin.password:}") String password){return args->{if(username!=null&&!username.isBlank()&&password!=null&&!password.isBlank()&&repo.findByUsername(username).isEmpty()){AdminUser u=new AdminUser();u.setUsername(username);u.setPasswordHash(encoder.encode(password));repo.save(u);}};} }
